create table tax_categories (active bit not null, cgst_rate decimal(5,2) not null, exempt bit not null, gst_rate decimal(5,2) not null, igst_rate decimal(5,2) not null, sgst_rate decimal(5,2) not null, tax_inclusive bit, business_id bigint not null, created_at datetime(6) not null, id bigint not null auto_increment, updated_at datetime(6) not null, version bigint, hsn_code varchar(20), name varchar(80) not null, primary key (id)) engine=InnoDB;
create table user_branches (branch_id bigint not null, user_id bigint not null, primary key (branch_id, user_id)) engine=InnoDB;
create table user_roles (role_id bigint not null, user_id bigint not null, primary key (role_id, user_id)) engine=InnoDB;
create table users (active bit not null, failed_login_attempts integer not null, business_id bigint, created_at datetime(6) not null, default_branch_id bigint, id bigint not null auto_increment, last_login_at datetime(6), locked_until datetime(6), updated_at datetime(6) not null, version bigint, phone varchar(30), username varchar(60) not null, full_name varchar(120) not null, email varchar(150) not null, password_hash varchar(200) not null, pin_hash varchar(200), primary key (id)) engine=InnoDB;
